#!/usr/bin/env python3
"""
evaluate.py - Main evaluation entry point for hls_constant_time_compare_001

Grades inputs/mac_verify.cpp (+ inputs/mac_verify.h) by:
  1. Static scan (SR1, SR2) of the verify() function body for data-dependent
     early loop exits (return/break/goto inside the comparison loop).
  2. Static scan (SR3) of mac_verify.h for interface conformance and
     mac_verify.cpp for dynamic/heap allocation constructs.
  3. Compiling inputs/mac_verify.cpp against evaluation/harness_main.cpp with
     g++ and running the resulting binary to derive FR1-FR4 and the
     behavioral half of SR3.
"""

import os
import subprocess
import sys
import tempfile

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INPUTS_DIR = os.path.join(REPO_ROOT, "inputs")
EVAL_DIR = os.path.join(REPO_ROOT, "evaluation")

MAC_VERIFY_CPP = os.path.join(INPUTS_DIR, "mac_verify.cpp")
MAC_VERIFY_H = os.path.join(INPUTS_DIR, "mac_verify.h")
HARNESS_MAIN = os.path.join(EVAL_DIR, "harness_main.cpp")

results = {}  # requirement_id -> (bool_ok, reason)


def record(req_id, ok, reason=""):
    results[req_id] = (ok, reason)
    if ok:
        print("[TEST] PASS: {}".format(req_id))
    else:
        print("[TEST] FAIL: {}: {}".format(req_id, reason))


def fail_all(req_ids, reason):
    for r in req_ids:
        record(r, False, reason)


def main():
    # --- SETUP checks: required input files must exist ---
    missing = []
    for fname, fpath in [
        ("inputs/mac_verify.cpp", MAC_VERIFY_CPP),
        ("inputs/mac_verify.h", MAC_VERIFY_H),
    ]:
        if not os.path.isfile(fpath):
            missing.append(fname)

    if missing:
        for fname in missing:
            print("[TEST] FAIL: SETUP: {} not found".format(fname))
        sys.exit(1)

    if not os.path.isfile(HARNESS_MAIN):
        print("[TEST] FAIL: SETUP: evaluation/harness_main.cpp not found")
        sys.exit(1)

    # --- Load private static-check module ---
    sys.path.insert(0, os.path.join(EVAL_DIR, "private"))
    try:
        import static_checks  # noqa: E402
    except Exception as e:
        print("[TEST] FAIL: SETUP: could not load evaluation/private/static_checks.py: {}".format(e))
        sys.exit(1)

    try:
        with open(MAC_VERIFY_CPP, "r", encoding="utf-8", errors="replace") as f:
            source_text = f.read()
    except Exception as e:
        print("[TEST] FAIL: SETUP: could not read inputs/mac_verify.cpp: {}".format(e))
        sys.exit(1)

    try:
        with open(MAC_VERIFY_H, "r", encoding="utf-8", errors="replace") as f:
            header_text = f.read()
    except Exception as e:
        print("[TEST] FAIL: SETUP: could not read inputs/mac_verify.h: {}".format(e))
        sys.exit(1)

    # --- SR1 / SR2: static structural checks (independent of compilation) ---
    try:
        sr1_ok, sr1_reason = static_checks.check_sr1(source_text)
    except Exception as e:
        sr1_ok, sr1_reason = False, "static_checks.check_sr1 raised exception: {}".format(e)

    try:
        sr2_ok, sr2_reason = static_checks.check_sr2(source_text)
    except Exception as e:
        sr2_ok, sr2_reason = False, "static_checks.check_sr2 raised exception: {}".format(e)

    record("SR1", sr1_ok, sr1_reason)
    record("SR2", sr2_ok, sr2_reason)

    # --- SR3 static sub-checks: interface conformance and no dynamic alloc ---
    try:
        sr3_iface_ok, sr3_iface_reason = static_checks.check_sr3_interface(header_text)
    except Exception as e:
        sr3_iface_ok, sr3_iface_reason = False, "static_checks.check_sr3_interface raised exception: {}".format(e)

    try:
        sr3_alloc_ok, sr3_alloc_reason = static_checks.check_sr3_dynamic_alloc(source_text)
    except Exception as e:
        sr3_alloc_ok, sr3_alloc_reason = False, "static_checks.check_sr3_dynamic_alloc raised exception: {}".format(e)

    # --- Compile inputs/mac_verify.cpp + evaluation/harness_main.cpp ---
    behavioral_ids = ["FR1", "FR2", "FR3", "FR4", "SR3"]

    # If either static SR3 sub-check already fails, we still want to attempt
    # compilation/behavioral checks for the other requirements, but SR3's
    # final verdict must reflect the static failure regardless of the
    # behavioral outcome.
    sr3_static_ok = sr3_iface_ok and sr3_alloc_ok
    if not sr3_iface_ok:
        sr3_static_reason = sr3_iface_reason
    elif not sr3_alloc_ok:
        sr3_static_reason = sr3_alloc_reason
    else:
        sr3_static_reason = ""

    with tempfile.TemporaryDirectory() as tmpdir:
        binary_path = os.path.join(tmpdir, "harness")
        compile_cmd = [
            "g++",
            "-std=c++11",
            "-O2",
            "-I", INPUTS_DIR,
            "-o", binary_path,
            MAC_VERIFY_CPP,
            HARNESS_MAIN,
        ]

        try:
            compile_proc = subprocess.run(
                compile_cmd,
                cwd=REPO_ROOT,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=30,
            )
        except subprocess.TimeoutExpired:
            fail_all(behavioral_ids, "compile failed: timed out after 30s")
            finish_with_sr3_override(sr3_static_ok, sr3_static_reason)
            return
        except Exception as e:
            fail_all(behavioral_ids, "compile failed: {}".format(e))
            finish_with_sr3_override(sr3_static_ok, sr3_static_reason)
            return

        if compile_proc.returncode != 0:
            stderr_text = compile_proc.stderr.decode("utf-8", errors="replace")
            first_line = next(
                (line for line in stderr_text.splitlines() if line.strip()),
                "unknown compiler error",
            )
            fail_all(behavioral_ids, "compile failed: {}".format(first_line))
            finish_with_sr3_override(sr3_static_ok, sr3_static_reason)
            return

        # --- Run the compiled binary ---
        try:
            run_proc = subprocess.run(
                [binary_path],
                cwd=REPO_ROOT,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=10,
            )
        except subprocess.TimeoutExpired:
            fail_all(behavioral_ids, "run crashed/timed out: execution exceeded 10s")
            finish_with_sr3_override(sr3_static_ok, sr3_static_reason)
            return
        except Exception as e:
            fail_all(behavioral_ids, "run crashed/timed out: {}".format(e))
            finish_with_sr3_override(sr3_static_ok, sr3_static_reason)
            return

        stdout_text = run_proc.stdout.decode("utf-8", errors="replace")

        if run_proc.returncode != 0:
            fail_all(
                behavioral_ids,
                "run crashed/timed out: exit code {}".format(run_proc.returncode),
            )
            finish_with_sr3_override(sr3_static_ok, sr3_static_reason)
            return

        # --- Parse harness output ---
        parsed = {}
        for line in stdout_text.splitlines():
            line = line.strip()
            if line.startswith("FR1_RESULT"):
                parts = line.split()
                if len(parts) == 3:
                    parsed["FR1"] = (parts[1], parts[2])
            elif line.startswith("FR2_RESULT"):
                parts = line.split()
                if len(parts) == 3:
                    parsed["FR2"] = (parts[1], parts[2])
            elif line.startswith("FR4_RESULT"):
                parts = line.split()
                if len(parts) == 3:
                    parsed["FR4"] = (parts[1], parts[2])
            elif line.startswith("SR3_ALLOC_COUNT"):
                parts = line.split()
                if len(parts) == 2:
                    parsed["SR3"] = parts[1]

        # FR1: pass == total, total >= 20
        if "FR1" in parsed:
            try:
                p, t = int(parsed["FR1"][0]), int(parsed["FR1"][1])
                if t < 20:
                    record("FR1", False, "FR1_RESULT total={} is below required minimum of 20".format(t))
                elif p != t:
                    record("FR1", False, "FR1_RESULT {}/{} identical-tag pairs verified true".format(p, t))
                else:
                    record("FR1", True)
            except ValueError:
                record("FR1", False, "malformed FR1_RESULT output: {}".format(parsed["FR1"]))
        else:
            record("FR1", False, "harness did not print FR1_RESULT line")

        # FR2: pass == total, total >= 16*20 (single-byte) + multi-byte cases
        if "FR2" in parsed:
            try:
                p, t = int(parsed["FR2"][0]), int(parsed["FR2"][1])
                if t < 16 * 20:
                    record("FR2", False, "FR2_RESULT total={} is below required minimum coverage".format(t))
                elif p != t:
                    record("FR2", False, "FR2_RESULT {}/{} mismatch cases correctly rejected".format(p, t))
                else:
                    record("FR2", True)
            except ValueError:
                record("FR2", False, "malformed FR2_RESULT output: {}".format(parsed["FR2"]))
        else:
            record("FR2", False, "harness did not print FR2_RESULT line")

        # FR3: compile succeeded and binary ran to completion (already established)
        record("FR3", True)

        # FR4: pass == total over fixed edge-case set
        if "FR4" in parsed:
            try:
                p, t = int(parsed["FR4"][0]), int(parsed["FR4"][1])
                if t < 6:
                    record("FR4", False, "FR4_RESULT total={} is below required minimum of 6 edge cases".format(t))
                elif p != t:
                    record("FR4", False, "FR4_RESULT {}/{} zero/0xFF edge cases correct".format(p, t))
                else:
                    record("FR4", True)
            except ValueError:
                record("FR4", False, "malformed FR4_RESULT output: {}".format(parsed["FR4"]))
        else:
            record("FR4", False, "harness did not print FR4_RESULT line")

        # SR3: combine static interface check, static no-dynamic-alloc check,
        # and behavioral alloc-count check.
        if not sr3_static_ok:
            record("SR3", False, sr3_static_reason)
        elif "SR3" in parsed:
            try:
                alloc_count = int(parsed["SR3"])
                if alloc_count == 0:
                    record("SR3", True)
                else:
                    record("SR3", False, "detected {} heap allocation(s) during verify() calls".format(alloc_count))
            except ValueError:
                record("SR3", False, "malformed SR3_ALLOC_COUNT output: {}".format(parsed["SR3"]))
        else:
            record("SR3", False, "harness did not print SR3_ALLOC_COUNT line")

    finish()


def finish_with_sr3_override(sr3_static_ok, sr3_static_reason):
    """Called when compile/run failed before behavioral SR3 could be
    evaluated. SR3's already-recorded FAIL (from fail_all) is overridden
    with the static reason only if the static checks are the actual cause;
    otherwise the compile/run failure reason (already recorded) stands."""
    if not sr3_static_ok:
        results["SR3"] = (False, sr3_static_reason)
        print("[TEST] FAIL: SR3: {}".format(sr3_static_reason))
    finish()


def finish():
    all_ok = all(ok for ok, _ in results.values())
    required_ids = {"FR1", "FR2", "FR3", "FR4", "SR1", "SR2", "SR3"}
    missing_ids = required_ids - set(results.keys())
    if missing_ids:
        for mid in missing_ids:
            print("[TEST] FAIL: {}: requirement was never evaluated".format(mid))
        all_ok = False
    sys.exit(0 if all_ok else 1)


if __name__ == "__main__":
    main()

#include "mac_verify.h"

#include <cstdio>
#include <cstdlib>
#include <cstddef>
#include <new>
#include <random>

// ---------------------------------------------------------------------
// Global allocation counter for SR3. We override the global operator new
// / operator new[] so that any heap allocation performed anywhere in the
// process (including, in particular, inside verify()) during the
// measurement window increments this counter. Plain C arrays on the
// stack do not go through these operators, so precomputing test vectors
// as local arrays before the measurement window does not perturb the
// count.
// ---------------------------------------------------------------------
static unsigned long g_alloc_count = 0;

void* operator new(std::size_t size) {
    ++g_alloc_count;
    void* p = std::malloc(size ? size : 1);
    if (!p) {
        std::fprintf(stderr, "operator new: allocation failed\n");
        std::exit(1);
    }
    return p;
}

void* operator new[](std::size_t size) {
    ++g_alloc_count;
    void* p = std::malloc(size ? size : 1);
    if (!p) {
        std::fprintf(stderr, "operator new[]: allocation failed\n");
        std::exit(1);
    }
    return p;
}

void operator delete(void* p) noexcept {
    std::free(p);
}

void operator delete(void* p, std::size_t) noexcept {
    std::free(p);
}

void operator delete[](void* p) noexcept {
    std::free(p);
}

void operator delete[](void* p, std::size_t) noexcept {
    std::free(p);
}

// ---------------------------------------------------------------------
// Fixed-size plain-array vector containers (no STL containers so that we
// don't introduce incidental heap allocations before/after the
// measurement window).
// ---------------------------------------------------------------------

static const int NUM_BASE_TAGS = 25;
static const int NUM_POSITIONS = 16;
static const int NUM_MULTI_MISMATCH = 25;

// FR1: identical pairs
static unsigned char fr1_computed[NUM_BASE_TAGS][16];
static unsigned char fr1_received[NUM_BASE_TAGS][16];

// FR2: single-byte mismatch cases: NUM_BASE_TAGS * NUM_POSITIONS
static const int FR2_SINGLE_TOTAL = NUM_BASE_TAGS * NUM_POSITIONS;
static unsigned char fr2_single_computed[FR2_SINGLE_TOTAL][16];
static unsigned char fr2_single_received[FR2_SINGLE_TOTAL][16];

// FR2: multi-byte mismatch cases
static unsigned char fr2_multi_computed[NUM_MULTI_MISMATCH][16];
static unsigned char fr2_multi_received[NUM_MULTI_MISMATCH][16];

// FR4: fixed edge-case combos
struct Fr4Case {
    unsigned char computed[16];
    unsigned char received[16];
    bool expected;
};
static const int FR4_TOTAL = 8;
static Fr4Case fr4_cases[FR4_TOTAL];

// SR3: precomputed pairs to cycle through during the measurement window
static const int SR3_NUM_PAIRS = 50;
static const int SR3_NUM_CALLS = 1000;
static unsigned char sr3_computed[SR3_NUM_PAIRS][16];
static unsigned char sr3_received[SR3_NUM_PAIRS][16];

static void fill_random_tag(std::mt19937& rng, unsigned char tag[16]) {
    std::uniform_int_distribution<int> dist(0, 255);
    for (int i = 0; i < 16; ++i) {
        tag[i] = static_cast<unsigned char>(dist(rng));
    }
}

int main() {
    std::mt19937 rng(1234567u);
    std::uniform_int_distribution<int> byte_dist(0, 255);
    std::uniform_int_distribution<int> pos_dist(0, 15);
    std::uniform_int_distribution<int> nonzero_xor_dist(1, 255);

    // -------------------------------------------------------------
    // Build FR1 vectors: identical (computed, received) pairs
    // -------------------------------------------------------------
    for (int i = 0; i < NUM_BASE_TAGS; ++i) {
        fill_random_tag(rng, fr1_computed[i]);
        for (int b = 0; b < 16; ++b) {
            fr1_received[i][b] = fr1_computed[i][b];
        }
    }

    // -------------------------------------------------------------
    // Build FR2 single-byte-mismatch vectors: 25 base tags, each with a
    // single-byte flip at each of the 16 positions.
    // -------------------------------------------------------------
    unsigned char fr2_base[NUM_BASE_TAGS][16];
    for (int i = 0; i < NUM_BASE_TAGS; ++i) {
        fill_random_tag(rng, fr2_base[i]);
    }

    int idx = 0;
    for (int i = 0; i < NUM_BASE_TAGS; ++i) {
        for (int pos = 0; pos < NUM_POSITIONS; ++pos) {
            for (int b = 0; b < 16; ++b) {
                fr2_single_computed[idx][b] = fr2_base[i][b];
                fr2_single_received[idx][b] = fr2_base[i][b];
            }
            unsigned char xor_val = static_cast<unsigned char>(nonzero_xor_dist(rng));
            fr2_single_received[idx][pos] = static_cast<unsigned char>(fr2_single_received[idx][pos] ^ xor_val);
            ++idx;
        }
    }

    // -------------------------------------------------------------
    // Build FR2 multi-byte-mismatch vectors
    // -------------------------------------------------------------
    for (int i = 0; i < NUM_MULTI_MISMATCH; ++i) {
        fill_random_tag(rng, fr2_multi_computed[i]);
        for (int b = 0; b < 16; ++b) {
            fr2_multi_received[i][b] = fr2_multi_computed[i][b];
        }
        // Flip a random number of distinct positions (between 2 and 5)
        std::uniform_int_distribution<int> num_flips_dist(2, 5);
        int num_flips = num_flips_dist(rng);
        bool flipped[16] = { false };
        int flips_done = 0;
        int guard = 0;
        while (flips_done < num_flips && guard < 1000) {
            int p = pos_dist(rng);
            ++guard;
            if (!flipped[p]) {
                unsigned char xor_val = static_cast<unsigned char>(nonzero_xor_dist(rng));
                fr2_multi_received[i][p] = static_cast<unsigned char>(fr2_multi_received[i][p] ^ xor_val);
                flipped[p] = true;
                ++flips_done;
            }
        }
    }

    // -------------------------------------------------------------
    // Build FR4 edge-case combos: all-zero and all-0xFF tags, as
    // computed/received, in every equal and unequal combination.
    // -------------------------------------------------------------
    unsigned char all_zero[16];
    unsigned char all_ff[16];
    for (int b = 0; b < 16; ++b) {
        all_zero[b] = 0x00;
        all_ff[b] = 0xFF;
    }

    // Case 0: zero vs zero -> true
    for (int b = 0; b < 16; ++b) { fr4_cases[0].computed[b] = all_zero[b]; fr4_cases[0].received[b] = all_zero[b]; }
    fr4_cases[0].expected = true;

    // Case 1: ff vs ff -> true
    for (int b = 0; b < 16; ++b) { fr4_cases[1].computed[b] = all_ff[b]; fr4_cases[1].received[b] = all_ff[b]; }
    fr4_cases[1].expected = true;

    // Case 2: zero vs ff -> false
    for (int b = 0; b < 16; ++b) { fr4_cases[2].computed[b] = all_zero[b]; fr4_cases[2].received[b] = all_ff[b]; }
    fr4_cases[2].expected = false;

    // Case 3: ff vs zero -> false
    for (int b = 0; b < 16; ++b) { fr4_cases[3].computed[b] = all_ff[b]; fr4_cases[3].received[b] = all_zero[b]; }
    fr4_cases[3].expected = false;

    // Case 4: zero vs random-nonzero-first-byte -> false
    {
        unsigned char rnd[16];
        for (int b = 0; b < 16; ++b) rnd[b] = all_zero[b];
        rnd[0] = 0x01;
        for (int b = 0; b < 16; ++b) { fr4_cases[4].computed[b] = all_zero[b]; fr4_cases[4].received[b] = rnd[b]; }
        fr4_cases[4].expected = false;
    }

    // Case 5: ff vs random-changed-last-byte -> false
    {
        unsigned char rnd[16];
        for (int b = 0; b < 16; ++b) rnd[b] = all_ff[b];
        rnd[15] = 0xFE;
        for (int b = 0; b < 16; ++b) { fr4_cases[5].computed[b] = all_ff[b]; fr4_cases[5].received[b] = rnd[b]; }
        fr4_cases[5].expected = false;
    }

    // Case 6: zero vs zero with one middle byte changed -> false
    {
        unsigned char rnd[16];
        for (int b = 0; b < 16; ++b) rnd[b] = all_zero[b];
        rnd[8] = 0x80;
        for (int b = 0; b < 16; ++b) { fr4_cases[6].computed[b] = all_zero[b]; fr4_cases[6].received[b] = rnd[b]; }
        fr4_cases[6].expected = false;
    }

    // Case 7: ff computed vs ff received but one byte cleared -> false
    {
        unsigned char rnd[16];
        for (int b = 0; b < 16; ++b) rnd[b] = all_ff[b];
        rnd[3] = 0x00;
        for (int b = 0; b < 16; ++b) { fr4_cases[7].computed[b] = all_ff[b]; fr4_cases[7].received[b] = rnd[b]; }
        fr4_cases[7].expected = false;
    }

    // -------------------------------------------------------------
    // Build SR3 precomputed pairs: mix of matching and mismatching tags,
    // constructed entirely before the measurement window begins.
    // -------------------------------------------------------------
    for (int i = 0; i < SR3_NUM_PAIRS; ++i) {
        fill_random_tag(rng, sr3_computed[i]);
        for (int b = 0; b < 16; ++b) {
            sr3_received[i][b] = sr3_computed[i][b];
        }
        if (i % 2 == 1) {
            int p = pos_dist(rng);
            unsigned char xor_val = static_cast<unsigned char>(nonzero_xor_dist(rng));
            sr3_received[i][p] = static_cast<unsigned char>(sr3_received[i][p] ^ xor_val);
        }
    }

    // =================================================================
    // Run FR1: identical pairs must all verify true
    // =================================================================
    {
        int pass = 0;
        int total = NUM_BASE_TAGS;
        for (int i = 0; i < NUM_BASE_TAGS; ++i) {
            bool result = verify(fr1_computed[i], fr1_received[i]);
            if (result == true) {
                ++pass;
            }
        }
        std::printf("FR1_RESULT %d %d\n", pass, total);
    }

    // =================================================================
    // Run FR2: all single-byte and multi-byte mismatch cases must be
    // rejected (verify() returns false).
    // =================================================================
    {
        int pass = 0;
        int total = FR2_SINGLE_TOTAL + NUM_MULTI_MISMATCH;

        for (int i = 0; i < FR2_SINGLE_TOTAL; ++i) {
            bool result = verify(fr2_single_computed[i], fr2_single_received[i]);
            if (result == false) {
                ++pass;
            }
        }

        for (int i = 0; i < NUM_MULTI_MISMATCH; ++i) {
            bool result = verify(fr2_multi_computed[i], fr2_multi_received[i]);
            if (result == false) {
                ++pass;
            }
        }

        std::printf("FR2_RESULT %d %d\n", pass, total);
    }

    // =================================================================
    // Run FR4: all-zero / all-0xFF edge cases plus near-edge variants
    // =================================================================
    {
        int pass = 0;
        int total = FR4_TOTAL;
        for (int i = 0; i < FR4_TOTAL; ++i) {
            bool result = verify(fr4_cases[i].computed, fr4_cases[i].received);
            if (result == fr4_cases[i].expected) {
                ++pass;
            }
        }
        std::printf("FR4_RESULT %d %d\n", pass, total);
    }

    // =================================================================
    // Run SR3: measure heap allocations strictly during repeated verify()
    // invocations over precomputed stack-array pairs. No other allocating
    // operation should occur inside this loop.
    // =================================================================
    {
        g_alloc_count = 0;
        volatile bool sink = false; // prevent the loop from being optimized away
        for (int call = 0; call < SR3_NUM_CALLS; ++call) {
            int idx2 = call % SR3_NUM_PAIRS;
            bool result = verify(sr3_computed[idx2], sr3_received[idx2]);
            sink = result;
        }
        (void)sink;
        std::printf("SR3_ALLOC_COUNT %lu\n", g_alloc_count);
    }

    return 0;
}

"""
evaluation/private/static_checks.py

Hidden-from-participant static structural checks for SR1, SR2, and SR3.

These checks are intentionally *fail-on-presence* only: they look for the
data-dependent early-exit construct (SR1/SR2), an interface deviation from
the pinned fixed-size signature (SR3 interface half), and dynamic/heap
allocation constructs (SR3 no-alloc half) that are the actual
vulnerabilities being guarded against. A correct, hardened implementation
that scans all 16 bytes unconditionally, keeps the pinned two-parameter
fixed-16-byte-array signature, and uses only fixed-size stack buffers will
simply not contain any of these constructs and will therefore pass
vacuously.

Anchor: the shipped baseline's comparison loop is

    for (int i = 0; i < 16; ++i) {
        if (computed_tag[i] != received_tag[i]) {
            return false;
        }
    }

which contains a `return` (and hence trips both SR1 and SR2) inside the
loop body.

Anchor: the SR3 mutant redefines the interface with a pointer+length
signature and a heap-allocated diff buffer, e.g.

    bool verify(const unsigned char* computed_tag, const unsigned char* received_tag, size_t len = 16) {
        unsigned char* diff = (unsigned char*)malloc(len);
        ...
        free(diff);
    }

which SR3's interface check must reject (extra/defaulted `len` parameter,
pointer instead of fixed-size array) and which SR3's alloc-scan check must
reject (via `malloc`/`free`).

All check_* functions return a `(bool_ok, reason_string)` tuple.
`reason_string` is empty when `bool_ok` is True.
"""


def _strip_comments_and_strings(text):
    """Blank out //, /* */ comments and "..."/'...' literals, preserving
    the original character offsets (so brace/paren counting downstream
    stays correct) but eliminating false matches of loop/return keywords
    or banned tokens that might otherwise appear inside comments or
    string literals."""
    result = list(text)
    n = len(text)
    i = 0
    while i < n:
        c = text[i]
        if c == '/' and i + 1 < n and text[i + 1] == '/':
            j = i
            while j < n and text[j] != '\n':
                result[j] = ' '
                j += 1
            i = j
        elif c == '/' and i + 1 < n and text[i + 1] == '*':
            j = i + 2
            while j + 1 < n and not (text[j] == '*' and text[j + 1] == '/'):
                j += 1
            end = min(j + 2, n)
            for k in range(i, end):
                result[k] = ' '
            i = end
        elif c == '"':
            j = i + 1
            result[i] = ' '
            while j < n and text[j] != '"':
                if text[j] == '\\' and j + 1 < n:
                    result[j] = ' '
                    result[j + 1] = ' '
                    j += 2
                    continue
                result[j] = ' '
                j += 1
            if j < n:
                result[j] = ' '
                j += 1
            i = j
        elif c == "'":
            j = i + 1
            result[i] = ' '
            while j < n and text[j] != "'":
                if text[j] == '\\' and j + 1 < n:
                    result[j] = ' '
                    result[j + 1] = ' '
                    j += 2
                    continue
                result[j] = ' '
                j += 1
            if j < n:
                result[j] = ' '
                j += 1
            i = j
        else:
            i += 1
    return ''.join(result)


def _is_word_char(ch):
    return ch.isalnum() or ch == '_'


def _find_token(text, token, start=0):
    """Find the next word-boundary-matched occurrence of `token` in
    `text` at or after `start`. Returns the start index, or -1."""
    idx = start
    n = len(text)
    tlen = len(token)
    while True:
        pos = text.find(token, idx)
        if pos == -1:
            return -1
        before_ok = (pos == 0) or (not _is_word_char(text[pos - 1]))
        after_idx = pos + tlen
        after_ok = (after_idx >= n) or (not _is_word_char(text[after_idx]))
        if before_ok and after_ok:
            return pos
        idx = pos + 1


def _contains_token(text, token):
    return _find_token(text, token, 0) != -1


def _next_keyword(text, start, keywords):
    """Find the earliest word-boundary-matched occurrence, at or after
    `start`, of any keyword in `keywords`. Returns (keyword, start_idx,
    end_idx) or None if none found."""
    best = None
    for kw in keywords:
        pos = _find_token(text, kw, start)
        if pos != -1:
            if best is None or pos < best[1]:
                best = (kw, pos, pos + len(kw))
    return best


def _match_balanced(text, open_idx, open_ch, close_ch):
    """Given the index of an opening delimiter (already confirmed to be
    `open_ch`), return the index just past the matching closing
    delimiter, or -1 if unbalanced."""
    n = len(text)
    depth = 1
    k = open_idx + 1
    while k < n and depth > 0:
        if text[k] == open_ch:
            depth += 1
        elif text[k] == close_ch:
            depth -= 1
        k += 1
    if depth != 0:
        return -1
    return k


def _find_function_body(stripped_text):
    """Locate the definition of `verify(...)` (matching the pinned
    signature name) in `stripped_text` (comments/strings already
    blanked) and return the text of its body (the content strictly
    between the outermost `{` and its matching `}`). Returns None if no
    function *definition* (as opposed to a declaration) is found."""
    n = len(stripped_text)
    search_from = 0
    while True:
        pos = _find_token(stripped_text, "verify", search_from)
        if pos == -1:
            return None
        search_from = pos + 1

        j = pos + len("verify")
        while j < n and stripped_text[j].isspace():
            j += 1
        if j >= n or stripped_text[j] != '(':
            continue

        k = _match_balanced(stripped_text, j, '(', ')')
        if k == -1:
            continue

        m = k
        while m < n and stripped_text[m].isspace():
            m += 1

        if m < n and stripped_text[m] == '{':
            p = _match_balanced(stripped_text, m, '{', '}')
            if p == -1:
                continue
            body_start = m + 1
            body_end = p - 1
            return stripped_text[body_start:body_end]
        else:
            # This occurrence is a declaration (e.g. ends with ';') or
            # something else that isn't a function definition; keep
            # searching for the actual definition.
            continue


def _find_loops(body_text):
    """Find every `for`/`while`/`do-while` loop construct in
    `body_text` and return a list of the text of each loop's own body
    (the statement or braced block controlled by the loop)."""
    loops = []
    i = 0
    n = len(body_text)
    while i < n:
        m = _next_keyword(body_text, i, ['for', 'while', 'do'])
        if m is None:
            break
        kw, kw_start, kw_end = m

        if kw in ('for', 'while'):
            j = kw_end
            while j < n and body_text[j].isspace():
                j += 1
            if j < n and body_text[j] == '(':
                k = _match_balanced(body_text, j, '(', ')')
                if k == -1:
                    i = kw_end
                    continue
                mm = k
                while mm < n and body_text[mm].isspace():
                    mm += 1
                if mm < n and body_text[mm] == '{':
                    p = _match_balanced(body_text, mm, '{', '}')
                    if p == -1:
                        i = kw_end
                        continue
                    loops.append(body_text[mm + 1:p - 1])
                    i = p
                    continue
                else:
                    semi = body_text.find(';', mm)
                    if semi == -1:
                        i = mm
                        continue
                    loops.append(body_text[mm:semi + 1])
                    i = semi + 1
                    continue
            else:
                i = kw_end
                continue

        elif kw == 'do':
            j = kw_end
            while j < n and body_text[j].isspace():
                j += 1
            if j < n and body_text[j] == '{':
                p = _match_balanced(body_text, j, '{', '}')
                if p == -1:
                    i = kw_end
                    continue
                loops.append(body_text[j + 1:p - 1])
                i = p
                continue
            else:
                # `do` without a braced body is unusual; skip past it to
                # avoid an infinite loop.
                i = kw_end
                continue
        else:
            i = kw_end

    return loops


def check_sr1(source_text):
    """SR1: the comparison loop (if any) must not contain a data-dependent
    early exit (`return`, `break`, or `goto`) that would make its trip
    count depend on buffer contents. A fully unrolled implementation
    with no loop construct at all vacuously satisfies this."""
    stripped = _strip_comments_and_strings(source_text)
    body = _find_function_body(stripped)
    if body is None:
        return False, "could not locate a definition of verify() in inputs/mac_verify.cpp"

    loops = _find_loops(body)
    if not loops:
        return True, ""

    for loop_body in loops:
        for token in ('return', 'break', 'goto'):
            if _contains_token(loop_body, token):
                return False, (
                    "a loop inside verify() contains a data-dependent early exit "
                    "('{}'), so its iteration count is not fixed at 16 regardless "
                    "of buffer contents".format(token)
                )
    return True, ""


def check_sr2(source_text):
    """SR2: the final boolean result must not be returned from mid-loop
    partial state; any loop body must not contain a `return`. A fully
    unrolled implementation with no loop construct vacuously satisfies
    this."""
    stripped = _strip_comments_and_strings(source_text)
    body = _find_function_body(stripped)
    if body is None:
        return False, "could not locate a definition of verify() in inputs/mac_verify.cpp"

    loops = _find_loops(body)
    if not loops:
        return True, ""

    for loop_body in loops:
        if _contains_token(loop_body, 'return'):
            return False, (
                "a loop inside verify() contains a 'return', indicating the boolean "
                "result may be produced from partial state before the full 16-byte "
                "scan completes"
            )
    return True, ""


def _split_top_level_commas(text):
    """Split `text` on commas that are not nested inside any
    (), [], or {} delimiter. Returns a list of (possibly empty after
    stripping) parameter substrings."""
    parts = []
    depth_paren = 0
    depth_bracket = 0
    depth_brace = 0
    current = []
    for ch in text:
        if ch == '(':
            depth_paren += 1
        elif ch == ')':
            depth_paren -= 1
        elif ch == '[':
            depth_bracket += 1
        elif ch == ']':
            depth_bracket -= 1
        elif ch == '{':
            depth_brace += 1
        elif ch == '}':
            depth_brace -= 1

        if ch == ',' and depth_paren == 0 and depth_bracket == 0 and depth_brace == 0:
            parts.append(''.join(current))
            current = []
        else:
            current.append(ch)
    parts.append(''.join(current))
    return parts


def _find_verify_paramlist(stripped_text):
    """Locate a `verify(` occurrence in `stripped_text` (declaration or
    definition; comments/strings already blanked) and return the raw
    text between its matching parentheses. Returns None if not found."""
    n = len(stripped_text)
    pos = _find_token(stripped_text, "verify", 0)
    while pos != -1:
        j = pos + len("verify")
        while j < n and stripped_text[j].isspace():
            j += 1
        if j < n and stripped_text[j] == '(':
            k = _match_balanced(stripped_text, j, '(', ')')
            if k != -1:
                return stripped_text[j + 1:k - 1]
        pos = _find_token(stripped_text, "verify", pos + 1)
    return None


# Length/size-typed tokens that would indicate a pointer+length
# redefinition of the interface rather than the pinned fixed-size
# 16-byte-array signature.
#
# NOTE: 'unsigned' was previously (incorrectly) included here. Every
# valid parameter of the pinned signature is itself typed
# 'const unsigned char ...[16]', so a bare 'unsigned' token is a required
# substring of every correct parameter and must never be treated as a
# length/size-type indicator. Removing it does not weaken detection of
# the SR3 mutant's added length parameter, since that mutant is already
# rejected by the exactly-two-parameters check below regardless of which
# type token the extra parameter uses.
_LENGTH_TYPE_TOKENS = (
    "size_t", "ssize_t", "int", "long", "short",
    "uint32_t", "uint64_t", "int32_t", "int64_t", "std::size_t",
)


def check_sr3_interface(header_text):
    """SR3 (interface half): the verify() declaration in mac_verify.h
    must match the pinned two-parameter, fixed-16-byte-array signature
    exactly:

        bool verify(const unsigned char computed_tag[16],
                    const unsigned char received_tag[16]);

    Rejects:
      - any parameter count other than exactly 2,
      - any parameter containing a default value ('='),
      - any variadic parameter ('...'),
      - any additional length/size-typed parameter (e.g. `size_t len = 16`),
      - any parameter that is not an `unsigned char` array-or-pointer type
        (with `const` required somewhere in the parameter).

    Vulnerability anchor: the SR3 mutant redefines the signature as
    `bool verify(const unsigned char* computed_tag, const unsigned char* received_tag, size_t len = 16)`
    -- an extra defaulted length parameter that must be rejected here.
    """
    stripped = _strip_comments_and_strings(header_text)

    paramlist_raw = _find_verify_paramlist(stripped)
    if paramlist_raw is None:
        return False, "could not locate a verify( declaration in inputs/mac_verify.h"

    paramlist_raw = paramlist_raw.strip()
    if paramlist_raw == "" or paramlist_raw == "void":
        return False, "verify() declaration in mac_verify.h takes no parameters; expected exactly 2 fixed-size unsigned-char array parameters"

    params = [p.strip() for p in _split_top_level_commas(paramlist_raw)]
    params = [p for p in params if p != ""]

    if len(params) != 2:
        return False, (
            "verify() declaration in mac_verify.h has {} parameter(s); expected exactly 2 "
            "(a variadic, defaulted-length, or pointer+length redefinition of the pinned "
            "signature is not permitted)".format(len(params))
        )

    for param in params:
        if '=' in param:
            return False, (
                "verify() parameter '{}' contains a default value; the pinned signature "
                "does not permit defaulted/optional parameters (e.g. an added length "
                "parameter with a default)".format(param.strip())
            )
        if '...' in param:
            return False, (
                "verify() parameter '{}' is variadic; the pinned signature does not "
                "permit variadic parameters".format(param.strip())
            )
        for tok in _LENGTH_TYPE_TOKENS:
            if _contains_token(param, tok):
                return False, (
                    "verify() parameter '{}' appears to introduce a length/size-typed "
                    "parameter ('{}'); the pinned signature takes only two fixed-size "
                    "16-byte 'const unsigned char' buffers, with no separate length "
                    "argument".format(param.strip(), tok)
                )
        if not _contains_token(param, "const"):
            return False, (
                "verify() parameter '{}' is missing 'const'; the pinned signature requires "
                "'const unsigned char' buffers".format(param.strip())
            )
        if not _contains_token(param, "unsigned") or not _contains_token(param, "char"):
            return False, (
                "verify() parameter '{}' is not an 'unsigned char' buffer as required by "
                "the pinned signature".format(param.strip())
            )
        # Must be either an array form (contains '[' ... ']') or a
        # pointer form (contains '*'); either is acceptable for a
        # "const unsigned char computed_tag[16]"-equivalent parameter,
        # since arrays decay to pointers in the ABI, but nothing else
        # (e.g. a bare value type, a reference to something else) is.
        if '[' not in param and '*' not in param:
            return False, (
                "verify() parameter '{}' is neither an array nor a pointer form of "
                "'const unsigned char'; the pinned signature requires a fixed-size "
                "16-byte buffer parameter".format(param.strip())
            )

    return True, ""


# Vulnerability in SR3 mutant: "unsigned char* diff = (unsigned char*)malloc(len);"
# and "free(diff);" used for a heap-allocated comparison buffer instead of the
# pinned fixed-size 16-byte stack arrays.
_DYNAMIC_ALLOC_TOKENS = (
    "malloc", "calloc", "realloc", "free", "alloca",
    "new", "std::vector", "std::string",
)


def check_sr3_dynamic_alloc(source_text):
    """SR3 (no-dynamic-allocation half): fail-on-presence scan of
    mac_verify.cpp for dynamic/heap allocation constructs. malloc/calloc/
    realloc/free bypass any operator-new override used by the behavioral
    SR3 counter in the harness, so this static scan is required to catch
    them.

    Vulnerability anchor: the SR3 mutant's
    `unsigned char* diff = (unsigned char*)malloc(len); ... free(diff);`
    heap diff-buffer pattern.
    """
    stripped = _strip_comments_and_strings(source_text)

    for token in _DYNAMIC_ALLOC_TOKENS:
        if _contains_token(stripped, token):
            return False, (
                "inputs/mac_verify.cpp contains a dynamic/heap allocation construct "
                "('{}'); the comparison path must use only fixed-size stack-resident "
                "16-byte buffers, with no malloc/calloc/realloc/free/alloca/new or "
                "variable-length container (std::vector/std::string)".format(token)
            )

    return True, ""
